SELECT DISTINCTROW Segnalazioni.[Record numero], Segnalazioni.[Reclamo numero], Segnalazioni.Data, Segnalazioni.Difetto, Segnalazioni.Commessa, Segnalazioni.[Famiglia dei prodotti], Segnalazioni.[Kg reclamati], Segnalazioni.Motivazioni, Segnalazioni.Commento, Segnalazioni.Esterno, Segnalazioni.[Ufficio 1], Segnalazioni.[Ufficio 2], Segnalazioni.[Ufficio 3], Segnalazioni.[Ufficio 4], Segnalazioni.[Ufficio 5], Segnalazioni.[Ufficio 6], DATI.CODPROD, DATI.DESPROD, DATI.FINITURA, DATI.SPESSORE, DATI.ALTEZZA, DATI.LARGHEZZA, DATI.ORIGINE, DATI.ORDINE, DATI.MACCHINA, DATI.NUMCOMM, DATI.ANCLI_1_DESCLI, DATI.RETE, DATI.CODCLI, DATI.ANCLI_DESCLI, DATI.DATAENT, DATI.QTAUSC
FROM DATI INNER JOIN Segnalazioni ON DATI.NUMCOMM = Segnalazioni.Commessa
WHERE ((Segnalazioni.[Famiglia dei prodotti] Like [Inserire la famiglia di prodotti cercata]));
